(function(){"use strict";if(window.plugin_netflix_theme_ready)return;window.plugin_netflix_theme_ready=true;var THEME_CSS="/* ============================================\n   Netflix Theme for Lampa TV\n   ============================================ */\n\n:root {\n    --nf-red: #E50914;\n    --nf-dark-red: #B20710;\n    --nf-bg: #141414;\n    --nf-surface: #181818;\n    --nf-black: #000000;\n    --nf-text: #FFFFFF;\n    --nf-text-secondary: #E5E5E5;\n    --nf-text-dim: #999999;\n    --nf-text-muted: rgba(255, 255, 255, 0.7);\n    --nf-card-radius: 0.3em;\n    --nf-transition: cubic-bezier(0.25, 0.46, 0.45, 0.94);\n    --nf-transition-bounce: cubic-bezier(0.16, 1, 0.3, 1);\n    --nf-shadow-focus: 0 0 0 2px var(--nf-red), 0 8px 32px rgba(229, 9, 20, 0.35);\n    --nf-shadow-card: 0 4px 16px rgba(0, 0, 0, 0.6);\n}\n\n/* ---- Base / Body ---- */\nbody {\n    background-color: var(--nf-bg) !important;\n    color: var(--nf-text) !important;\n    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif !important;\n}\n\n/* ---- Background ---- */\n.background {\n    opacity: 0.45 !important;\n}\n\n.background__one,\n.background__two {\n    filter: brightness(0.6) saturate(1.2) !important;\n}\n\n/* ---- Header ---- */\n.head {\n    background: linear-gradient(to bottom, rgba(0, 0, 0, 0.85) 0%, rgba(0, 0, 0, 0.5) 60%, transparent 100%) !important;\n}\n\n.head__body {\n    padding-top: 0.5em !important;\n    padding-bottom: 0.5em !important;\n}\n\n.head__logo-icon svg,\n.head__logo-icon img {\n    filter: brightness(0) saturate(100%) invert(11%) sepia(96%) saturate(6562%) hue-rotate(354deg) brightness(92%) contrast(100%) !important;\n}\n\n.head__action.focus,\n.head__action.hover {\n    background-color: var(--nf-red) !important;\n    color: var(--nf-text) !important;\n}\n\n.head__action {\n    background-color: rgba(255, 255, 255, 0.1) !important;\n    border-radius: 50% !important;\n    transition: background-color 0.25s var(--nf-transition), transform 0.25s var(--nf-transition) !important;\n}\n\n.head__action.focus {\n    transform: scale(1.1) !important;\n}\n\n.head__title {\n    color: var(--nf-text) !important;\n    font-weight: 700 !important;\n}\n\n/* ---- Menu / Sidebar ---- */\n.menu {\n    background-color: rgba(0, 0, 0, 0.92) !important;\n    border-right: 1px solid rgba(229, 9, 20, 0.15) !important;\n}\n\n.menu__item {\n    color: var(--nf-text-secondary) !important;\n    border-radius: 0.4em !important;\n    transition: all 0.2s var(--nf-transition) !important;\n    margin-bottom: 0.15em !important;\n}\n\n.menu__item.focus,\n.menu__item.hover {\n    background-color: var(--nf-red) !important;\n    color: var(--nf-text) !important;\n}\n\n.menu__item.active {\n    color: var(--nf-text) !important;\n    font-weight: 600 !important;\n}\n\n.menu__item.active::before {\n    content: '' !important;\n    position: absolute !important;\n    left: 0 !important;\n    top: 50% !important;\n    transform: translateY(-50%) !important;\n    width: 3px !important;\n    height: 60% !important;\n    background-color: var(--nf-red) !important;\n    border-radius: 0 2px 2px 0 !important;\n}\n\n.menu__ico {\n    color: inherit !important;\n}\n\n.menu__split {\n    border-color: rgba(255, 255, 255, 0.08) !important;\n}\n\n/* ---- Cards ---- */\n.card {\n    transition: transform 0.3s var(--nf-transition-bounce), opacity 0.3s ease !important;\n    border-radius: var(--nf-card-radius) !important;\n    overflow: visible !important;\n}\n\n.card__view {\n    border-radius: var(--nf-card-radius) !important;\n    overflow: hidden !important;\n    box-shadow: var(--nf-shadow-card) !important;\n    transition: box-shadow 0.3s var(--nf-transition) !important;\n    background-color: var(--nf-surface) !important;\n}\n\n.card__img {\n    border-radius: var(--nf-card-radius) !important;\n    transition: filter 0.3s ease !important;\n}\n\n.card.focus .card__view,\n.card.hover .card__view {\n    box-shadow: var(--nf-shadow-focus) !important;\n}\n\n.card.focus,\n.card.hover {\n    transform: scale(1.08) !important;\n    z-index: 5 !important;\n    position: relative !important;\n}\n\n.card:not(.focus):not(.hover) {\n    opacity: 0.8 !important;\n}\n\n.card.focus .card__img,\n.card.hover .card__img {\n    filter: brightness(1.05) !important;\n}\n\n/* Card title */\n.card__title {\n    color: var(--nf-text-secondary) !important;\n    font-size: 0.85em !important;\n    margin-top: 0.5em !important;\n    font-weight: 500 !important;\n    transition: color 0.2s ease !important;\n}\n\n.card.focus .card__title,\n.card.hover .card__title {\n    color: var(--nf-text) !important;\n}\n\n/* Card meta */\n.card__age {\n    color: var(--nf-text-dim) !important;\n}\n\n/* Card vote / rating */\n.card__vote {\n    background-color: var(--nf-red) !important;\n    color: var(--nf-text) !important;\n    border-radius: 0.25em !important;\n    font-weight: 700 !important;\n    font-size: 0.75em !important;\n    padding: 0.15em 0.4em !important;\n}\n\n/* Card quality badge */\n.card__quality {\n    background-color: var(--nf-red) !important;\n    color: var(--nf-text) !important;\n    border-radius: 0.2em !important;\n    font-weight: 600 !important;\n}\n\n/* Card type indicator */\n.card__type {\n    background-color: rgba(229, 9, 20, 0.85) !important;\n    color: var(--nf-text) !important;\n    border-radius: 0.2em !important;\n}\n\n/* ---- Netflix Overlay on Cards ---- */\n.nf-card-overlay {\n    position: absolute;\n    bottom: 0;\n    left: 0;\n    right: 0;\n    padding: 0.8em 0.6em 0.5em;\n    background: linear-gradient(to top, rgba(0, 0, 0, 0.92) 0%, rgba(0, 0, 0, 0.55) 45%, transparent 100%);\n    border-radius: 0 0 var(--nf-card-radius) var(--nf-card-radius);\n    opacity: 0;\n    transform: translateY(0.3em);\n    transition: opacity 0.3s ease, transform 0.3s var(--nf-transition);\n    pointer-events: none;\n    z-index: 2;\n}\n\n.card.focus .nf-card-overlay,\n.card.hover .nf-card-overlay {\n    opacity: 1;\n    transform: translateY(0);\n}\n\n.nf-card-overlay__title {\n    font-size: 0.72em;\n    font-weight: 700;\n    color: var(--nf-text);\n    line-height: 1.2;\n    margin-bottom: 0.2em;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n}\n\n.nf-card-overlay__meta {\n    font-size: 0.6em;\n    color: var(--nf-text-dim);\n    display: flex;\n    align-items: center;\n    gap: 0.4em;\n}\n\n.nf-card-overlay__year {\n    color: #46D369;\n    font-weight: 600;\n}\n\n/* ---- Content Rows / Items Line ---- */\n.items-line {\n    margin-bottom: 0.5em !important;\n}\n\n.items-line__head {\n    padding-bottom: 0.4em !important;\n}\n\n.items-line__title {\n    color: var(--nf-text) !important;\n    font-weight: 700 !important;\n    font-size: 1.3em !important;\n}\n\n.items-line__more {\n    color: var(--nf-text-dim) !important;\n    transition: color 0.2s ease !important;\n}\n\n.items-line__more:hover,\n.items-line__more.focus {\n    color: var(--nf-red) !important;\n}\n\n/* ---- Row Entrance Animation ---- */\n.nf-row-animated {\n    animation: nf-row-slide-in 0.5s var(--nf-transition-bounce) forwards;\n}\n\n.nf-row-animated .card {\n    animation: nf-card-slide-in 0.4s var(--nf-transition-bounce) forwards;\n    opacity: 0;\n}\n\n.nf-row-animated .card:nth-child(1) { animation-delay: 0.05s; }\n.nf-row-animated .card:nth-child(2) { animation-delay: 0.1s; }\n.nf-row-animated .card:nth-child(3) { animation-delay: 0.15s; }\n.nf-row-animated .card:nth-child(4) { animation-delay: 0.2s; }\n.nf-row-animated .card:nth-child(5) { animation-delay: 0.25s; }\n.nf-row-animated .card:nth-child(6) { animation-delay: 0.3s; }\n.nf-row-animated .card:nth-child(7) { animation-delay: 0.35s; }\n.nf-row-animated .card:nth-child(8) { animation-delay: 0.4s; }\n.nf-row-animated .card:nth-child(9) { animation-delay: 0.45s; }\n.nf-row-animated .card:nth-child(10) { animation-delay: 0.5s; }\n\n@keyframes nf-row-slide-in {\n    from {\n        opacity: 0;\n        transform: translateY(1.5em);\n    }\n    to {\n        opacity: 1;\n        transform: translateY(0);\n    }\n}\n\n@keyframes nf-card-slide-in {\n    from {\n        opacity: 0;\n        transform: translateX(1.2em);\n    }\n    to {\n        opacity: 1;\n        transform: translateX(0);\n    }\n}\n\n/* ---- Hero Billboard ---- */\n.nf-hero {\n    position: fixed;\n    top: 0;\n    left: 0;\n    right: 0;\n    height: 55vh;\n    z-index: 1;\n    pointer-events: none;\n    opacity: 0;\n    transition: opacity 0.6s ease;\n    overflow: hidden;\n}\n\n.nf-hero.visible {\n    opacity: 1;\n}\n\n.nf-hero__image {\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    filter: brightness(0.55) saturate(1.1);\n}\n\n.nf-hero__gradient {\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    background: linear-gradient(to right, rgba(0, 0, 0, 0.88) 0%, rgba(0, 0, 0, 0.45) 50%, transparent 100%),\n                linear-gradient(to top, var(--nf-bg) 0%, rgba(20, 20, 20, 0.7) 25%, transparent 50%);\n}\n\n.nf-hero__info {\n    position: absolute;\n    bottom: 18%;\n    left: 3.5%;\n    max-width: 42%;\n    z-index: 2;\n}\n\n.nf-hero__title {\n    font-size: 2.8em;\n    font-weight: 800;\n    color: var(--nf-text);\n    line-height: 1.1;\n    margin-bottom: 0.3em;\n    text-shadow: 0 2px 8px rgba(0, 0, 0, 0.8);\n    overflow: hidden;\n    display: -webkit-box;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n}\n\n.nf-hero__meta {\n    display: flex;\n    align-items: center;\n    gap: 0.8em;\n    margin-bottom: 0.5em;\n    font-size: 0.95em;\n}\n\n.nf-hero__year {\n    color: #46D369;\n    font-weight: 700;\n}\n\n.nf-hero__vote {\n    background-color: var(--nf-red);\n    color: var(--nf-text);\n    padding: 0.15em 0.6em;\n    border-radius: 0.25em;\n    font-weight: 700;\n    font-size: 0.9em;\n}\n\n.nf-hero__genres {\n    color: var(--nf-text-muted);\n    font-size: 0.85em;\n}\n\n.nf-hero__overview {\n    color: var(--nf-text-secondary);\n    font-size: 0.9em;\n    line-height: 1.5;\n    margin-top: 0.5em;\n    overflow: hidden;\n    display: -webkit-box;\n    -webkit-line-clamp: 3;\n    -webkit-box-orient: vertical;\n    text-shadow: 0 1px 4px rgba(0, 0, 0, 0.7);\n}\n\n/* ---- Scroll ---- */\n.scroll--mask::before,\n.scroll--mask::after {\n    display: none !important;\n}\n\n/* ---- Activity / Screens ---- */\n.activity__body {\n    padding-top: 1em !important;\n}\n\n/* ---- Modal ---- */\n.modal__content {\n    background-color: var(--nf-surface) !important;\n    border: 1px solid rgba(255, 255, 255, 0.08) !important;\n    border-radius: 0.6em !important;\n    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.7) !important;\n}\n\n.modal__title {\n    color: var(--nf-text) !important;\n    font-weight: 700 !important;\n}\n\n.modal__text {\n    color: var(--nf-text-secondary) !important;\n}\n\n.modal__button.focus,\n.modal__button.hover {\n    background-color: var(--nf-red) !important;\n    color: var(--nf-text) !important;\n}\n\n/* ---- Settings ---- */\n.settings__title {\n    color: var(--nf-text) !important;\n    font-weight: 700 !important;\n}\n\n.settings-folder {\n    transition: background-color 0.2s ease !important;\n    border-radius: 0.4em !important;\n}\n\n.settings-folder.focus,\n.settings-folder.hover {\n    background-color: rgba(229, 9, 20, 0.2) !important;\n}\n\n.settings-param {\n    border-radius: 0.4em !important;\n    transition: background-color 0.2s ease !important;\n}\n\n.settings-param.focus,\n.settings-param.hover {\n    background-color: rgba(229, 9, 20, 0.15) !important;\n}\n\n.settings-param__name {\n    color: var(--nf-text) !important;\n}\n\n.settings-param__value {\n    color: var(--nf-red) !important;\n    font-weight: 600 !important;\n}\n\n.settings-param__descr {\n    color: var(--nf-text-dim) !important;\n}\n\n/* ---- Buttons ---- */\n.simple-button {\n    border-radius: 0.3em !important;\n    transition: all 0.2s var(--nf-transition) !important;\n    color: var(--nf-text) !important;\n}\n\n.simple-button.focus,\n.simple-button.hover {\n    background-color: var(--nf-red) !important;\n    color: var(--nf-text) !important;\n    transform: scale(1.03) !important;\n}\n\n/* ---- Full Detail View ---- */\n.full-start__title {\n    font-weight: 800 !important;\n    color: var(--nf-text) !important;\n}\n\n.full-start__tagline {\n    color: var(--nf-text-muted) !important;\n    font-style: italic !important;\n}\n\n.full-start__rate .rate--imdb,\n.full-start__rate .rate--tmdb {\n    color: var(--nf-text) !important;\n}\n\n.full-start__rate .rate--kp {\n    color: var(--nf-text) !important;\n}\n\n.full-start-new__rate-line .rate--imdb,\n.full-start-new__rate-line .rate--tmdb {\n    color: var(--nf-text) !important;\n}\n\n.full-start__buttons .selector.focus,\n.full-start__buttons .selector.hover {\n    background-color: var(--nf-red) !important;\n    color: var(--nf-text) !important;\n}\n\n.full-start__buttons .selector {\n    background-color: rgba(255, 255, 255, 0.1) !important;\n    border-radius: 0.3em !important;\n    transition: all 0.2s var(--nf-transition) !important;\n}\n\n.full-start__desc {\n    color: var(--nf-text-secondary) !important;\n    line-height: 1.6 !important;\n}\n\n/* ---- Torrent / Source List ---- */\n.torrent-item {\n    border-radius: 0.3em !important;\n    transition: background-color 0.2s ease !important;\n}\n\n.torrent-item.focus,\n.torrent-item.hover {\n    background-color: rgba(229, 9, 20, 0.18) !important;\n}\n\n/* ---- Notification ---- */\n.noty {\n    background-color: var(--nf-surface) !important;\n    border-left: 3px solid var(--nf-red) !important;\n    border-radius: 0.3em !important;\n    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5) !important;\n}\n\n/* ---- Player ---- */\n.player-panel {\n    background: linear-gradient(to top, rgba(0, 0, 0, 0.9) 0%, transparent 100%) !important;\n}\n\n.player-panel__progress .player-panel__position {\n    background-color: var(--nf-red) !important;\n}\n\n.player-panel__timeline-dot {\n    background-color: var(--nf-red) !important;\n    box-shadow: 0 0 8px rgba(229, 9, 20, 0.6) !important;\n}\n\n/* ---- Search ---- */\n.search__input {\n    background-color: rgba(255, 255, 255, 0.08) !important;\n    border: 1px solid rgba(255, 255, 255, 0.15) !important;\n    border-radius: 0.3em !important;\n    color: var(--nf-text) !important;\n    transition: border-color 0.2s ease !important;\n}\n\n.search__input:focus,\n.search__input.focus {\n    border-color: var(--nf-red) !important;\n    box-shadow: 0 0 0 1px rgba(229, 9, 20, 0.3) !important;\n}\n\n/* ---- Wrap ---- */\n.wrap__left {\n    background: linear-gradient(to right, rgba(0, 0, 0, 0.95) 0%, rgba(0, 0, 0, 0.8) 80%, transparent 100%) !important;\n}\n\n/* ---- Filter ---- */\n.filter--icon {\n    border-radius: 0.3em !important;\n}\n\n.filter--icon.focus,\n.filter--icon.hover {\n    background-color: var(--nf-red) !important;\n}\n\n/* ---- Selector / Focus Items ---- */\n.selector.focus,\n.selector.hover {\n    background-color: rgba(229, 9, 20, 0.15) !important;\n}\n\n/* ---- Navigation Bar (Mobile) ---- */\n.navigation-bar {\n    background-color: rgba(0, 0, 0, 0.95) !important;\n    border-top: 1px solid rgba(229, 9, 20, 0.2) !important;\n}\n\n.navigation-bar__item.active .navigation-bar__icon {\n    color: var(--nf-red) !important;\n}\n\n.navigation-bar__item.active .navigation-bar__label {\n    color: var(--nf-red) !important;\n}\n\n/* ---- Scrollbar (Webkit) ---- */\n::-webkit-scrollbar {\n    width: 5px !important;\n    height: 5px !important;\n}\n\n::-webkit-scrollbar-track {\n    background: transparent !important;\n}\n\n::-webkit-scrollbar-thumb {\n    background: rgba(229, 9, 20, 0.5) !important;\n    border-radius: 3px !important;\n}\n\n::-webkit-scrollbar-thumb:hover {\n    background: var(--nf-red) !important;\n}\n\n/* ---- Intro Animation ---- */\n.nf-intro {\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    background: var(--nf-black);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 9999;\n    animation: nf-intro-fade 0.8s ease 2.2s forwards;\n    pointer-events: none;\n}\n\n.nf-intro__text {\n    font-size: 4em;\n    font-weight: 900;\n    color: var(--nf-red);\n    letter-spacing: 0.08em;\n    text-transform: uppercase;\n    animation: nf-intro-zoom 1.5s var(--nf-transition-bounce) forwards;\n    text-shadow: 0 0 40px rgba(229, 9, 20, 0.6), 0 0 80px rgba(229, 9, 20, 0.3);\n}\n\n@keyframes nf-intro-zoom {\n    0% {\n        transform: scale(3);\n        opacity: 0;\n        filter: blur(8px);\n    }\n    50% {\n        opacity: 1;\n        filter: blur(0);\n    }\n    100% {\n        transform: scale(1);\n        opacity: 1;\n        filter: blur(0);\n    }\n}\n\n@keyframes nf-intro-fade {\n    to {\n        opacity: 0;\n        visibility: hidden;\n    }\n}\n\n/* ---- Loading Spinner ---- */\n.loading {\n    color: var(--nf-red) !important;\n}\n\n.loading::after {\n    border-color: var(--nf-red) transparent transparent transparent !important;\n}\n\n/* ---- Empty State ---- */\n.empty__title {\n    color: var(--nf-text-dim) !important;\n}\n\n.empty__descr {\n    color: var(--nf-text-dim) !important;\n}\n\n/* ---- Layer / Resize Adjustments ---- */\n@media screen and (max-width: 580px) {\n    .nf-hero__title {\n        font-size: 1.6em;\n    }\n    .nf-hero__info {\n        max-width: 80%;\n    }\n    .nf-hero {\n        height: 40vh;\n    }\n}\n\n@media screen and (min-width: 581px) and (max-width: 1024px) {\n    .nf-hero__title {\n        font-size: 2em;\n    }\n    .nf-hero__info {\n        max-width: 55%;\n    }\n}\n";function inject(){try{if(document.getElementById("netflix-theme-css"))return;var s=document.createElement("style");s.id="netflix-theme-css";s.type="text/css";s.appendChild(document.createTextNode(THEME_CSS));(document.head||document.documentElement).appendChild(s);}catch(e){console.error("netflix-theme inject error:",e);}}function start(){inject();try{if(typeof Lampa!=="undefined"&&Lampa.Listener){Lampa.Listener.follow("app",function(e){if(e.type==="ready")inject();});}}catch(e){console.error("netflix-theme listener error:",e);}}function waitForReady(){if(document.body){start();}else{document.addEventListener("DOMContentLoaded",start);}}waitForReady();})();